"""Recursive-descent parser for minisql ``SELECT`` queries.

``parse`` accepts a single query (with an optional trailing semicolon) and
returns a :class:`minisql.ast.Query`.  Every expression node gets its ``text``
attribute filled with the exact source substring it was parsed from, which the
engine uses to name unaliased output columns.

Any syntax problem raises :class:`minisql.errors.QueryError`.
"""

from typing import List, Optional

from .ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Not,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)
from .errors import QueryError
from .lexer import KEYWORDS, Token, tokenize

__all__ = ["parse"]

#: Source operator spelling -> ``Binary.op`` spelling.  ``<>`` normalizes to
#: ``!=``.
_COMPARISON_OPS = {
    "=": "=",
    "!=": "!=",
    "<>": "!=",
    "<": "<",
    "<=": "<=",
    ">": ">",
    ">=": ">=",
}

#: Keyword comparison operators that may be negated by a preceding ``NOT``.
_NEGATABLE_COMPARISONS = frozenset({"IN", "BETWEEN", "LIKE"})

#: Keywords that start a comparison-level construct (used to reject chains).
_COMPARISON_WORDS = frozenset({"IS", "IN", "BETWEEN", "LIKE"})


def parse(sql: str) -> Query:
    """Parse one ``SELECT`` query from ``sql``."""
    return _Parser(sql).parse_query()


class _Parser:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # ------------------------------------------------------------------
    # Token helpers
    # ------------------------------------------------------------------
    def peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def advance(self) -> Token:
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def is_word(self, token: Token, word: str) -> bool:
        return token.kind == "IDENT" and token.value.upper() == word

    def peek_word(self) -> Optional[str]:
        token = self.peek()
        if token.kind == "IDENT":
            return token.value.upper()
        return None

    def match_word(self, word: str) -> bool:
        if self.is_word(self.peek(), word):
            self.advance()
            return True
        return False

    def expect_word(self, word: str) -> Token:
        if self.is_word(self.peek(), word):
            return self.advance()
        self.error("expected %s" % word)
        raise AssertionError("unreachable")  # pragma: no cover

    def peek_punct(self, char: str) -> bool:
        token = self.peek()
        return token.kind == "PUNCT" and token.value == char

    def expect_punct(self, char: str) -> Token:
        if self.peek_punct(char):
            return self.advance()
        self.error("expected %r" % char)
        raise AssertionError("unreachable")  # pragma: no cover

    def peek_op(self, op: str) -> bool:
        token = self.peek()
        return token.kind == "OP" and token.value == op

    def is_name_token(self, token: Token) -> bool:
        """True for a plain name: unquoted non-keyword or quoted identifier."""
        if token.kind == "QIDENT":
            return True
        return token.kind == "IDENT" and token.value.upper() not in KEYWORDS

    def error(self, message: str, token: Optional[Token] = None) -> None:
        token = token if token is not None else self.peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        raise QueryError(
            "%s at position %d (found %s)" % (message, token.start, _describe(token))
        )

    # ------------------------------------------------------------------
    # Source ranges
    # ------------------------------------------------------------------
    def token_text(self, token: Token) -> str:
        return self.sql[token.start : token.end]

    def span(self, start_index: int) -> str:
        """Exact source text from token ``start_index`` to the last consumed."""
        start = self.tokens[start_index].start
        end = self.tokens[self.pos - 1].end
        return self.sql[start:end]

    # ------------------------------------------------------------------
    # Query
    # ------------------------------------------------------------------
    def parse_query(self) -> Query:
        if not self.is_word(self.peek(), "SELECT"):
            self.error("expected SELECT")
        self.advance()

        distinct = self.match_word("DISTINCT")

        star = False
        columns: List[SelectItem] = []
        if self.peek_op("*"):
            star = True
            self.advance()
            if not self.is_word(self.peek(), "FROM"):
                self.error("'*' must be the only select item")
        else:
            columns = self.parse_select_items()

        self.expect_word("FROM")
        table = self.parse_table_name()

        query = Query(distinct=distinct, star=star, columns=columns, table=table)

        if self.match_word("WHERE"):
            query.where = self.parse_expr()

        if self.match_word("GROUP"):
            self.expect_word("BY")
            query.group_by = self.parse_expr_list()

        if self.match_word("HAVING"):
            query.having = self.parse_expr()

        if self.match_word("ORDER"):
            self.expect_word("BY")
            query.order_by = self.parse_order_items()

        if self.match_word("LIMIT"):
            query.limit = self.parse_limit_value("LIMIT")
            if self.match_word("OFFSET"):
                query.offset = self.parse_limit_value("OFFSET")
        elif self.is_word(self.peek(), "OFFSET"):
            self.error("OFFSET requires a preceding LIMIT")

        if self.peek_punct(";"):
            self.advance()

        if self.peek().kind != "EOF":
            self.error("unexpected token after query")

        return query

    def parse_table_name(self) -> str:
        token = self.peek()
        if self.is_name_token(token):
            self.advance()
            return token.value
        self.error("expected a table name")
        raise AssertionError("unreachable")  # pragma: no cover

    def parse_select_items(self) -> List[SelectItem]:
        items = [self.parse_select_item()]
        while self.peek_punct(","):
            self.advance()
            items.append(self.parse_select_item())
        return items

    def parse_select_item(self) -> SelectItem:
        expr = self.parse_expr()
        alias: Optional[str] = None
        if self.match_word("AS"):
            alias = self.parse_name("expected an alias after AS")
        elif self.is_name_token(self.peek()):
            alias = self.parse_name("expected an alias")
        return SelectItem(expr=expr, alias=alias)

    def parse_name(self, message: str) -> str:
        token = self.peek()
        if self.is_name_token(token):
            self.advance()
            return token.value
        self.error(message)
        raise AssertionError("unreachable")  # pragma: no cover

    def parse_expr_list(self) -> List[Expr]:
        items = [self.parse_expr()]
        while self.peek_punct(","):
            self.advance()
            items.append(self.parse_expr())
        return items

    def parse_order_items(self) -> List[OrderItem]:
        items = [self.parse_order_item()]
        while self.peek_punct(","):
            self.advance()
            items.append(self.parse_order_item())
        return items

    def parse_order_item(self) -> OrderItem:
        expr = self.parse_expr()
        desc = False
        if self.match_word("DESC"):
            desc = True
        else:
            self.match_word("ASC")
        return OrderItem(expr=expr, desc=desc)

    def parse_limit_value(self, clause: str) -> int:
        token = self.peek()
        if token.kind == "NUMBER" and isinstance(token.value, int):
            self.advance()
            return token.value
        self.error("%s requires a non-negative integer" % clause)
        raise AssertionError("unreachable")  # pragma: no cover

    # ------------------------------------------------------------------
    # Expressions
    # ------------------------------------------------------------------
    def parse_expr(self) -> Expr:
        return self.parse_or()

    def parse_or(self) -> Expr:
        start = self.pos
        left = self.parse_and()
        while self.match_word("OR"):
            right = self.parse_and()
            left = Binary("OR", left, right, self.span(start))
        return left

    def parse_and(self) -> Expr:
        start = self.pos
        left = self.parse_not()
        while self.match_word("AND"):
            right = self.parse_not()
            left = Binary("AND", left, right, self.span(start))
        return left

    def parse_not(self) -> Expr:
        start = self.pos
        if self.match_word("NOT"):
            operand = self.parse_not()
            return Not(operand, self.span(start))
        return self.parse_comparison()

    def parse_comparison(self) -> Expr:
        start = self.pos
        left = self.parse_additive()

        token = self.peek()
        node: Optional[Expr] = None

        if token.kind == "OP" and token.value in _COMPARISON_OPS:
            self.advance()
            right = self.parse_additive()
            node = Binary(_COMPARISON_OPS[token.value], left, right)
        elif token.kind == "IDENT":
            word = token.value.upper()
            negated = False
            if word == "NOT":
                following = self.peek(1)
                if following.kind == "IDENT" and following.value.upper() in _NEGATABLE_COMPARISONS:
                    self.advance()  # consume NOT
                    negated = True
                    word = following.value.upper()

            if word == "IS":
                if negated:
                    self.error("NOT cannot precede IS")
                self.advance()
                is_not = self.match_word("NOT")
                self.expect_word("NULL")
                node = IsNull(left, is_not)
            elif word == "IN":
                self.advance()
                items = self.parse_in_items()
                node = InList(left, items, negated)
            elif word == "BETWEEN":
                self.advance()
                low = self.parse_additive()
                self.expect_word("AND")
                high = self.parse_additive()
                node = Between(left, low, high, negated)
            elif word == "LIKE":
                self.advance()
                pattern = self.parse_additive()
                node = Like(left, pattern, negated)

        if node is None:
            return left

        node.text = self.span(start)
        self.reject_chained_comparison()
        return node

    def parse_in_items(self) -> List[Expr]:
        self.expect_punct("(")
        items = [self.parse_additive()]
        while self.peek_punct(","):
            self.advance()
            items.append(self.parse_additive())
        self.expect_punct(")")
        return items

    def reject_chained_comparison(self) -> None:
        token = self.peek()
        if token.kind == "OP" and token.value in _COMPARISON_OPS:
            self.error("comparison operators cannot be chained")
        if token.kind == "IDENT":
            word = token.value.upper()
            if word in _COMPARISON_WORDS:
                self.error("comparison operators cannot be chained")
            if word == "NOT":
                following = self.peek(1)
                if (
                    following.kind == "IDENT"
                    and following.value.upper() in _NEGATABLE_COMPARISONS
                ):
                    self.error("comparison operators cannot be chained")

    def parse_additive(self) -> Expr:
        start = self.pos
        left = self.parse_multiplicative()
        while True:
            token = self.peek()
            if token.kind != "OP" or token.value not in ("+", "-", "||"):
                break
            self.advance()
            right = self.parse_multiplicative()
            left = Binary(token.value, left, right, self.span(start))
        return left

    def parse_multiplicative(self) -> Expr:
        start = self.pos
        left = self.parse_unary()
        while True:
            token = self.peek()
            if token.kind != "OP" or token.value not in ("*", "/"):
                break
            self.advance()
            right = self.parse_unary()
            left = Binary(token.value, left, right, self.span(start))
        return left

    def parse_unary(self) -> Expr:
        start = self.pos
        if self.peek_op("-"):
            self.advance()
            operand = self.parse_unary()
            return Unary("-", operand, self.span(start))
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        token = self.peek()

        if token.kind == "NUMBER":
            self.advance()
            return Literal(token.value, self.token_text(token))

        if token.kind == "STRING":
            self.advance()
            return Literal(token.value, self.token_text(token))

        if token.kind == "QIDENT":
            following = self.peek(1)
            if following.kind == "PUNCT" and following.value == "(":
                self.error("quoted names cannot be used as function names")
            self.advance()
            return Column(token.value, self.token_text(token))

        if token.kind == "IDENT":
            word = token.value.upper()
            if word == "NULL":
                self.advance()
                return Literal(None, self.token_text(token))
            if word == "TRUE":
                self.advance()
                return Literal(True, self.token_text(token))
            if word == "FALSE":
                self.advance()
                return Literal(False, self.token_text(token))
            if word in KEYWORDS:
                self.error("unexpected keyword %r" % token.value)

            following = self.peek(1)
            if following.kind == "PUNCT" and following.value == "(":
                return self.parse_function_call()
            self.advance()
            return Column(token.value, self.token_text(token))

        if token.kind == "PUNCT" and token.value == "(":
            start = self.pos
            self.advance()
            expr = self.parse_expr()
            self.expect_punct(")")
            expr.text = self.span(start)
            return expr

        if token.kind == "OP" and token.value == "*":
            self.error("'*' is not allowed here")

        self.error("expected an expression")
        raise AssertionError("unreachable")  # pragma: no cover

    def parse_function_call(self) -> Expr:
        start = self.pos
        name_token = self.advance()
        name = name_token.value.upper()
        self.expect_punct("(")

        if self.peek_op("*"):
            if name != "COUNT":
                self.error("'*' is only allowed as the argument of COUNT", name_token)
            self.advance()
            self.expect_punct(")")
            return Func(name, [], True, self.span(start))

        args: List[Expr] = []
        if not self.peek_punct(")"):
            args.append(self.parse_expr())
            while self.peek_punct(","):
                self.advance()
                args.append(self.parse_expr())
        self.expect_punct(")")

        return Func(name, args, False, self.span(start))


def _describe(token: Token) -> str:
    if token.kind == "EOF":
        return "end of query"
    if token.kind == "QIDENT":
        return "quoted name %r" % (token.value,)
    if token.kind == "STRING":
        return "string literal"
    if token.kind == "NUMBER":
        return "number %r" % (token.value,)
    if token.kind in ("IDENT", "OP", "PUNCT"):
        return "%r" % (token.value,)
    return token.kind
